class TextAnim {
    constructor(idName) {
        this.id = "";
        this.id = idName;
        this.dom = document.getElementById(this.id);
        console.log(this.dom);
        this.dom.style.gridColumn = "span " + Math.floor(Math.random() * 4 + 1);
        //this.divElement.style.gridRowStart = ""+Math.floor(Math.random()*5+1);  
    }
    setText(text) {
        if (!this.dom)
            return;
        this.dom.innerHTML = text;
    }
    play(title, delay = 0, callback = null) {
        if (!this.dom)
            return;
        const text = title;
        this.dom.innerHTML = title;
        this.dom.style.opacity = "0";
        if (delay == 0) {
            this.animation(text, callback);
        }
        else {
            setTimeout(() => {
                this.animation(text, callback);
            }, delay * 1000);
        }
    }
    animation(text, callback = null) {
        let i = 0;
        const interval = setInterval(() => {
            if (i < text.length) {
                if (i == 0) {
                    this.dom.innerHTML = "";
                }
                this.dom.innerHTML = text.substring(0, i + 1);
                this.dom.style.opacity = "1";
                i++;
            }
            else {
                if (callback != null) {
                    callback();
                }
                clearInterval(interval);
            }
        }, 40);
    }
}


