class JavisPoint {
    constructor() {
        this.ratio = 0;
        this.index = 0;
        this.offsetX = 0;
        this.offsetY = 0;
        this.vx = Math.random() * 2 - 1;
        this.vy = Math.random() * 2 - 1;
        this.random = false;
    }
    update() {
        this.offsetX += this.vx;
        this.offsetY += this.vy;
        this.vx *= 0.99;
        this.vy *= 0.99;
    }
}


