class VectorUtils {
    static limit(tgt, lim) {
        if (tgt.length() > lim) {
            tgt = tgt.normalize().multiplyScalar(lim);
        }
        return tgt;
    }
    static getLength(v1, v2) {
        var dx = v1.x - v2.x;
        var dy = v1.y - v2.y;
        var dz = v1.z - v2.z;
        var dist = Math.sqrt(dx * dx + dy * dy + dz * dz);
        return dist;
    }
}


